const rankingData = $node['Get Ranking Data'].json;
const backlinkData = $node['Get Backlink Data'].json;
const healthIssues = $node['Get Health Issues'].json;

// Process rankings
const rankings = Array.isArray(rankingData) ? rankingData : [rankingData];
const improved = rankings.filter(r => r.position_change < 0).length;
const declined = rankings.filter(r => r.position_change > 0).length;
const unchanged = rankings.filter(r => r.position_change === 0).length;
const top10 = rankings.filter(r => r.current_position <= 10).length;
const top3 = rankings.filter(r => r.current_position <= 3).length;

// Top movers
const topImproved = rankings
  .filter(r => r.position_change < 0)
  .sort((a, b) => a.position_change - b.position_change)
  .slice(0, 5);

const topDeclined = rankings
  .filter(r => r.position_change > 0)
  .sort((a, b) => b.position_change - a.position_change)
  .slice(0, 5);

// Backlinks
const bl = Array.isArray(backlinkData) ? backlinkData[0] : backlinkData;

// Health
const issues = Array.isArray(healthIssues) ? healthIssues : (healthIssues ? [healthIssues] : []);

const report = {
  period: `${new Date(Date.now() - 7*24*60*60*1000).toISOString().split('T')[0]} - ${new Date().toISOString().split('T')[0]}`,
  rankings: {
    total_tracked: rankings.length,
    top_3: top3,
    top_10: top10,
    improved: improved,
    declined: declined,
    unchanged: unchanged,
    top_improved: topImproved.map(r => ({ keyword: r.keyword, change: r.position_change, position: r.current_position })),
    top_declined: topDeclined.map(r => ({ keyword: r.keyword, change: r.position_change, position: r.current_position }))
  },
  backlinks: {
    total: bl?.total_backlinks || 0,
    new_this_week: bl?.new_backlinks || 0,
    lost_this_week: bl?.lost_backlinks || 0,
    avg_dr: bl?.avg_dr || 0,
    high_quality: bl?.high_quality_count || 0
  },
  health: {
    issues_found: issues.length,
    critical_pages_affected: issues.filter(i => i.status_code >= 500).length
  }
};

return [{ json: report }];

